def merge_intervals(intervals):
    if not intervals:
        return []

    sorted_intervals = sorted(intervals, key=lambda interval: (interval[0], interval[1]))

    merged = [list(sorted_intervals[0])]

    for start, end in sorted_intervals[1:]:
        last = merged[-1]
        if start <= last[1]:
            last[1] = max(last[1], end)
        else:
            merged.append([start, end])

    return merged

import heapq


def toposort(nodes, edges):
    adj = {node: set() for node in nodes}
    indeg = {node: 0 for node in nodes}

    for src, dst in edges:
        if src == dst:
            raise ValueError("self loop detected")
        if dst not in adj[src]:
            adj[src].add(dst)
            indeg[dst] += 1

    heap = [node for node in nodes if indeg[node] == 0]
    heapq.heapify(heap)

    result = []
    while heap:
        node = heapq.heappop(heap)
        result.append(node)
        for neighbor in adj[node]:
            indeg[neighbor] -= 1
            if indeg[neighbor] == 0:
                heapq.heappush(heap, neighbor)

    if len(result) != len(nodes):
        raise ValueError("cycle detected")

    return result

def stable_batches(items, limit):
    if limit <= 0:
        raise ValueError("limit must be positive")
    for _, weight in items:
        if weight <= 0 or weight > limit:
            raise ValueError("weight must be between 1 and limit")
    batches = []
    current = []
    current_weight = 0
    for name, weight in items:
        if current and current_weight + weight > limit:
            batches.append(current)
            current = []
            current_weight = 0
        current.append(name)
        current_weight += weight
    if current:
        batches.append(current)
    return batches

import re


def parse_env(text):
    key_re = re.compile(r'[A-Za-z_][A-Za-z0-9_]*')
    result = {}
    for raw in text.splitlines():
        line = raw.strip()
        if not line or line.startswith('#'):
            continue
        if '=' not in line:
            raise ValueError(f"invalid environment assignment: {raw!r}")
        key, _, value = line.partition('=')
        key = key.strip()
        value = value.strip()
        if not key_re.fullmatch(key):
            raise ValueError(f"invalid key: {key!r}")
        if len(value) >= 2 and value[0] == value[-1] and value[0] in ('"', "'"):
            value = value[1:-1]
        result[key] = value
    return result

import math


def retry_delay(attempt, base, cap):
    if attempt < 0:
        raise ValueError("attempt must be nonnegative")
    if base < 0:
        raise ValueError("base must be nonnegative")
    if cap < 0:
        raise ValueError("cap must be nonnegative")

    # base == 0 makes base * 2**attempt == 0; cap == 0 caps everything at 0.
    if base == 0 or cap == 0:
        return 0.0

    # Compare attempt with log2(cap/base) so we never build 2**attempt as a
    # giant int (attempt can be 10**9) and never let base * 2**attempt overflow.
    #
    #   base * 2**attempt >= cap
    # <=> 2**attempt >= cap / base
    # <=> attempt >= log2(cap / base)
    #
    # If that holds, the product is >= cap (or would overflow to inf), so the
    # min is cap. Otherwise the true product is < cap, hence finite, so it is
    # the min and cannot overflow.
    if attempt >= math.log2(cap / base):
        return float(cap)

    return float(base * (2.0 ** attempt))

def fifo_admit(active, queued, budget, slots):
    if any(q > budget for q in queued):
        raise ValueError("a queued reservation exceeds the whole budget")

    active_sum = sum(active)
    active_len = len(active)

    admitted = []
    used_sum = active_sum
    for q in queued:
        if active_len + len(admitted) < slots and used_sum + q <= budget:
            admitted.append(q)
            used_sum += q
        else:
            break

    remaining = queued[len(admitted):]
    return admitted, remaining
